"""Embedded assets for vlambda UI."""

UI_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>vlambda</title>\n<link rel="icon" href="/favicon.ico" type="image/x-icon">\n<script src="https://cdn.jsdelivr.net/npm/chart.js@4"></script>\n<style>\n* { box-sizing: border-box; margin: 0; padding: 0; }\nbody { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, monospace; background: #0d1117; color: #c9d1d9; }\na { color: #58a6ff; text-decoration: none; }\na:hover { text-decoration: underline; }\n.container { max-width: 960px; margin: 0 auto; padding: 20px; }\nh1 { font-size: 24px; margin-bottom: 16px; color: #f0f6fc; }\nh2 { font-size: 18px; margin-bottom: 12px; color: #f0f6fc; }\n.card { background: #161b22; border: 1px solid #30363d; border-radius: 8px; padding: 16px; margin-bottom: 16px; }\n.btn { padding: 6px 12px; border: 1px solid #30363d; border-radius: 6px; background: #21262d; color: #c9d1d9; cursor: pointer; font-size: 13px; }\n.btn:hover { background: #30363d; }\n.btn-primary { background: #238636; border-color: #238636; color: #fff; }\n.btn-primary:hover { background: #2ea043; }\n.btn-danger { background: #da3633; border-color: #da3633; color: #fff; }\n.btn-danger:hover { background: #f85149; }\n.btn-sm { padding: 3px 8px; font-size: 12px; }\ninput, textarea { background: #0d1117; border: 1px solid #30363d; color: #c9d1d9; padding: 8px; border-radius: 6px; font-size: 13px; width: 100%; font-family: monospace; }\ntextarea { min-height: 200px; resize: vertical; }\nlabel { display: block; margin-bottom: 4px; font-size: 13px; color: #8b949e; }\n.form-group { margin-bottom: 12px; }\ntable { width: 100%; border-collapse: collapse; }\nth, td { padding: 8px; text-align: left; border-bottom: 1px solid #30363d; font-size: 13px; vertical-align: middle; }\nth { color: #8b949e; font-weight: 600; }\ntr:hover { background: #161b22; }\n.badge { display: inline-block; padding: 2px 6px; border-radius: 4px; font-size: 11px; background: #30363d; }\n.badge-get { background: #1f6feb; }\n.badge-post { background: #238636; }\n.alert { padding: 8px 12px; border-radius: 6px; margin-bottom: 12px; font-size: 13px; }\n.alert-error { background: #3d1f1f; border: 1px solid #da3633; color: #f85149; }\n.alert-success { background: #1f3d1f; border: 1px solid #238636; color: #3fb950; }\n.hidden { display: none !important; }\n.flex { display: flex; gap: 8px; align-items: center; }\n.flex-between { display: flex; justify-content: space-between; align-items: center; }\n.mt { margin-top: 12px; }\n.mb { margin-bottom: 12px; }\npre { background: #0d1117; border: 1px solid #30363d; border-radius: 6px; padding: 12px; overflow-x: auto; font-size: 12px; white-space: pre-wrap; word-break: break-all; }\n.modal-overlay { position: fixed; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0,0,0,0.7); display: flex; align-items: center; justify-content: center; z-index: 100; }\n.modal { background: #161b22; border: 1px solid #30363d; border-radius: 8px; padding: 20px; max-width: 400px; width: 90%; }\n.nav { display: flex; gap: 16px; margin-bottom: 20px; padding-bottom: 12px; border-bottom: 1px solid #30363d; }\n.nav a { color: #8b949e; font-size: 14px; }\n.nav a.active { color: #f0f6fc; font-weight: 600; }\n</style>\n</head>\n<body>\n<div class="container">\n  <h1>vlambda</h1>\n  <div class="nav" id="nav">\n    <a href="#" id="nav-dashboard" class="active" onclick="showView(\'dashboard\');return false;">Dashboard</a>\n    <a href="#" id="nav-metrics" onclick="showView(\'metrics\');return false;">Metrics</a>\n    <a href="#" id="nav-logout" onclick="logout();return false;">Logout</a>\n  </div>\n\n  <div id="view-login" class="hidden">\n    <div class="card" style="max-width:400px;margin:40px auto;">\n      <h2>Login / Register</h2>\n      <div id="login-alert"></div>\n      <div class="form-group">\n        <label>Username</label>\n        <input type="text" id="username" placeholder="username">\n      </div>\n      <div class="form-group">\n        <label>Password</label>\n        <input type="password" id="password" placeholder="password">\n      </div>\n      <div class="flex">\n        <button class="btn btn-primary" onclick="doLogin()">Login</button>\n        <button class="btn" onclick="doRegister()">Register</button>\n      </div>\n    </div>\n  </div>\n\n  <div id="view-dashboard">\n    <div class="flex-between mb">\n      <h2>Your Lambdas</h2>\n      <button class="btn btn-primary" onclick="showCreate()">+ New Lambda</button>\n    </div>\n    <div id="dashboard-alert"></div>\n    <div id="create-form" class="card hidden">\n      <h2>New Lambda</h2>\n      <div class="form-group">\n        <label>Name (optional)</label>\n        <input type="text" id="name-input" placeholder="my-lambda">\n      </div>\n      <div class="form-group">\n        <label>Method</label>\n        <select id="method-select" style="background:#0d1117;border:1px solid #30363d;color:#c9d1d9;padding:8px;border-radius:6px;font-size:13px;width:100%;">\n          <option value="GET">GET</option>\n          <option value="POST">POST</option>\n          <option value="PUT">PUT</option>\n          <option value="PATCH">PATCH</option>\n          <option value="DELETE">DELETE</option>\n        </select>\n      </div>\n      <div class="form-group">\n        <label>Python Code</label>\n        <textarea id="code-input">def handler(request):\n    return {"msg": "hello", "path": request.path}</textarea>\n      </div>\n      <div class="flex">\n        <button class="btn btn-primary" onclick="createLambda()">Create</button>\n        <button class="btn" onclick="hideCreate()">Cancel</button>\n      </div>\n    </div>\n    <div class="card">\n      <table>\n        <thead><tr><th>Slug</th><th>Method</th><th>Actions</th></tr></thead>\n        <tbody id="lambda-list"></tbody>\n      </table>\n    </div>\n  </div>\n\n  <div id="view-editor" class="hidden">\n    <div class="flex-between mb">\n      <h2 id="editor-title">Edit Lambda</h2>\n      <button class="btn" onclick="showView(\'dashboard\')">Back</button>\n    </div>\n    <div id="editor-alert"></div>\n    <div class="card">\n      <div class="form-group">\n        <label>Name</label>\n        <input type="text" id="editor-name" placeholder="my-lambda">\n      </div>\n      <div class="form-group">\n        <label>Method</label>\n        <select id="editor-method" style="background:#0d1117;border:1px solid #30363d;color:#c9d1d9;padding:8px;border-radius:6px;font-size:13px;width:100%;">\n          <option value="GET">GET</option>\n          <option value="POST">POST</option>\n          <option value="PUT">PUT</option>\n          <option value="PATCH">PATCH</option>\n          <option value="DELETE">DELETE</option>\n        </select>\n      </div>\n      <div class="form-group">\n        <label>Code</label>\n        <textarea id="editor-code"></textarea>\n      </div>\n      <div class="flex mb">\n        <button class="btn btn-primary" onclick="saveLambda()">Save</button>\n        <button class="btn" onclick="runLambda()">Run</button>\n      </div>\n      <div id="run-result"></div>\n    </div>\n  </div>\n\n  <div id="view-metrics" class="hidden">\n    <h2>Metrics</h2>\n    <div class="card" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;margin-bottom:16px;">\n      <div><div style="color:#8b949e;font-size:12px;">Total Requests</div><div id="m-reqs" style="font-size:24px;font-weight:700;">0</div></div>\n      <div><div style="color:#8b949e;font-size:12px;">Errors</div><div id="m-errs" style="font-size:24px;font-weight:700;color:#f85149;">0</div></div>\n      <div><div style="color:#8b949e;font-size:12px;">Lambdas Created</div><div id="m-lambdas" style="font-size:24px;font-weight:700;color:#3fb950;">0</div></div>\n      <div><div style="color:#8b949e;font-size:12px;">Avg Latency (ms)</div><div id="m-lat" style="font-size:24px;font-weight:700;">0</div></div>\n    </div>\n    <div class="card">\n      <h2 style="font-size:14px;">Per-Lambda Invocations</h2>\n      <canvas id="chart-invocations" height="200"></canvas>\n    </div>\n    <div class="card">\n      <h2 style="font-size:14px;">Per-Lambda Latency (ms)</h2>\n      <canvas id="chart-latency" height="200"></canvas>\n    </div>\n    <button class="btn" onclick="loadMetrics()">Refresh</button>\n  </div>\n</div>\n\n<div id="delete-modal" class="modal-overlay hidden">\n  <div class="modal">\n    <h2>Delete Lambda?</h2>\n    <p style="margin:12px 0;color:#8b949e;">This action cannot be undone.</p>\n    <div class="flex">\n      <button class="btn btn-danger" onclick="confirmDelete()">Delete</button>\n      <button class="btn" onclick="closeModal()">Cancel</button>\n    </div>\n  </div>\n</div>\n\n<script>\nconst API = \'\';\nlet token = localStorage.getItem(\'vlambda_token\');\nlet currentSlug = null;\nlet lambdaNames = {};\nlet deleteTarget = null;\n\nfunction showAlert(id, msg, type) {\n  const el = document.getElementById(id);\n  el.innerHTML = \'<div class="alert alert-\' + type + \'">\' + msg + \'</div>\';\n  setTimeout(() => el.innerHTML = \'\', 4000);\n}\n\nfunction showView(name) {\n  document.querySelectorAll(\'[id^="view-"]\').forEach(e => e.classList.add(\'hidden\'));\n  document.getElementById(\'view-\' + name).classList.remove(\'hidden\');\n  document.querySelectorAll(\'.nav a\').forEach(a => a.classList.remove(\'active\'));\n  const nav = document.getElementById(\'nav-\' + name);\n  if (nav) nav.classList.add(\'active\');\n  if (name === \'dashboard\') loadLambdas();\n  if (name === \'metrics\') loadMetrics();\n}\n\nfunction checkAuth() {\n  if (!token) {\n    document.getElementById(\'view-login\').classList.remove(\'hidden\');\n    document.getElementById(\'view-dashboard\').classList.add(\'hidden\');\n    document.getElementById(\'view-editor\').classList.add(\'hidden\');\n    document.getElementById(\'view-metrics\').classList.add(\'hidden\');\n    document.getElementById(\'nav\').classList.add(\'hidden\');\n  } else {\n    document.getElementById(\'nav\').classList.remove(\'hidden\');\n    showView(\'dashboard\');\n  }\n}\n\nasync function doLogin() {\n  const u = document.getElementById(\'username\').value;\n  const p = document.getElementById(\'password\').value;\n  try {\n    const resp = await fetch(API + \'/login\', { method: \'POST\', body: u + \':\' + p });\n    const data = await resp.json();\n    if (resp.ok) {\n      token = data.token;\n      localStorage.setItem(\'vlambda_token\', token);\n      checkAuth();\n    } else {\n      showAlert(\'login-alert\', data.error || \'Login failed\', \'error\');\n    }\n  } catch (e) {\n    showAlert(\'login-alert\', \'Network error\', \'error\');\n  }\n}\n\nasync function doRegister() {\n  const u = document.getElementById(\'username\').value;\n  const p = document.getElementById(\'password\').value;\n  try {\n    const resp = await fetch(API + \'/register\', { method: \'POST\', body: u + \':\' + p });\n    const data = await resp.json();\n    if (resp.ok) {\n      showAlert(\'login-alert\', \'Registered! Please login.\', \'success\');\n    } else {\n      showAlert(\'login-alert\', data.error || \'Register failed\', \'error\');\n    }\n  } catch (e) {\n    showAlert(\'login-alert\', \'Network error\', \'error\');\n  }\n}\n\nfunction logout() {\n  token = null;\n  localStorage.removeItem(\'vlambda_token\');\n  checkAuth();\n}\n\nasync function loadLambdas() {\n  try {\n    const resp = await fetch(API + \'/vlambda\', { headers: { \'Authorization\': \'Bearer \' + token } });\n    const data = await resp.json();\n    const tbody = document.getElementById(\'lambda-list\');\n    tbody.innerHTML = \'\';\n    if (data.lambdas) {\n      data.lambdas.trim().split(\'\\n\').forEach(line => {\n        if (!line) return;\n        const parts = line.split(\'|\');\n        const slug = parts[0];\n        const name = parts[1] || \'\';\n        const method = parts[2];\n        lambdaNames[slug] = name;\n        const displayName = name ? name : slug;\n        const tr = document.createElement(\'tr\');\n        tr.innerHTML = \'<td><a href="/f/\' + slug + \'" target="_blank">\' + displayName + \'</a><br><span style="font-size:11px;color:#8b949e;">\' + slug + \'</span></td>\' +\n          \'<td><span class="badge badge-\' + method.toLowerCase() + \'">\' + method + \'</span></td>\' +\n          \'<td><span style="display:inline-flex;gap:4px;">\' +\n          \'<button class="btn btn-sm" onclick="invokeLambda(\\\'\' + slug + \'\\\', \\\'\' + method + \'\\\')">Run</button>\' +\n          \'<button class="btn btn-sm" onclick="editLambda(\\\'\' + slug + \'\\\')">Edit</button>\' +\n          \'<button class="btn btn-sm btn-danger" onclick="openDelete(\\\'\' + slug + \'\\\')">Del</button>\' +\n          \'</span></td>\';\n        tbody.appendChild(tr);\n      });\n    }\n  } catch (e) {\n    showAlert(\'dashboard-alert\', \'Failed to load lambdas\', \'error\');\n  }\n}\n\nfunction showCreate() {\n  document.getElementById(\'create-form\').classList.remove(\'hidden\');\n}\n\nfunction hideCreate() {\n  document.getElementById(\'create-form\').classList.add(\'hidden\');\n  document.getElementById(\'code-input\').value = \'\';\n  document.getElementById(\'name-input\').value = \'\';\n}\n\nasync function createLambda() {\n  const code = document.getElementById(\'code-input\').value;\n  const method = document.getElementById(\'method-select\').value;\n  const name = document.getElementById(\'name-input\').value;\n  try {\n    const resp = await fetch(API + \'/vlambda?method=\' + method + \'&name=\' + encodeURIComponent(name), {\n      method: \'POST\',\n      headers: { \'Authorization\': \'Bearer \' + token, \'Content-Type\': \'text/plain\' },\n      body: code\n    });\n    const data = await resp.json();\n    if (resp.ok) {\n      showAlert(\'dashboard-alert\', \'Created: \' + data.slug, \'success\');\n      hideCreate();\n      loadLambdas();\n    } else {\n      showAlert(\'dashboard-alert\', data.error || \'Create failed\', \'error\');\n    }\n  } catch (e) {\n    showAlert(\'dashboard-alert\', \'Network error\', \'error\');\n  }\n}\n\nasync function editLambda(slug) {\n  currentSlug = slug;\n  document.getElementById(\'editor-title\').textContent = \'Edit: \' + slug;\n  document.getElementById(\'editor-code\').value = \'Loading...\';\n  document.getElementById(\'editor-name\').value = lambdaNames[slug] || \'\';\n  document.getElementById(\'run-result\').innerHTML = \'\';\n  showView(\'editor\');\n  try {\n    const resp = await fetch(API + \'/vlambda/\' + slug, { headers: { \'Authorization\': \'Bearer \' + token } });\n    if (resp.ok) {\n      const code = await resp.text();\n      document.getElementById(\'editor-code\').value = code;\n    } else {\n      document.getElementById(\'editor-code\').value = \'\';\n      showAlert(\'editor-alert\', \'Failed to load code\', \'error\');\n    }\n  } catch (e) {\n    document.getElementById(\'editor-code\').value = \'\';\n    showAlert(\'editor-alert\', \'Network error\', \'error\');\n  }\n}\n\nasync function saveLambda() {\n  const code = document.getElementById(\'editor-code\').value;\n  const method = document.getElementById(\'editor-method\').value;\n  const name = document.getElementById(\'editor-name\').value;\n  try {\n    const resp = await fetch(API + \'/vlambda/\' + currentSlug + \'?method=\' + method + \'&name=\' + encodeURIComponent(name), {\n      method: \'PUT\',\n      headers: { \'Authorization\': \'Bearer \' + token, \'Content-Type\': \'text/plain\' },\n      body: code\n    });\n    const data = await resp.json();\n    if (resp.ok) {\n      showAlert(\'editor-alert\', \'Saved!\', \'success\');\n    } else {\n      showAlert(\'editor-alert\', data.error || \'Save failed\', \'error\');\n    }\n  } catch (e) {\n    showAlert(\'editor-alert\', \'Network error\', \'error\');\n  }\n}\n\nasync function runLambda() {\n  const code = document.getElementById(\'editor-code\').value;\n  const resultDiv = document.getElementById(\'run-result\');\n  resultDiv.innerHTML = \'<pre>Running...</pre>\';\n  const method = document.getElementById(\'editor-method\').value;\n  try {\n    const resp = await fetch(API + \'/vlambda?method=\' + method, {\n      method: \'POST\',\n      headers: { \'Authorization\': \'Bearer \' + token, \'Content-Type\': \'text/plain\' },\n      body: code\n    });\n    const data = await resp.json();\n    if (!resp.ok) {\n      resultDiv.innerHTML = \'<pre style="color:#f85149">\' + (data.error || \'Error\') + \'</pre>\';\n      return;\n    }\n    const invokeOpts = { method: method };\n    if (method === \'POST\' || method === \'PUT\' || method === \'PATCH\') {\n      invokeOpts.headers = { \'Content-Type\': \'application/json\' };\n      invokeOpts.body = \'{}\';\n    }\n    const invokeResp = await fetch(API + \'/f/\' + data.slug, invokeOpts);\n    const result = await invokeResp.text();\n    resultDiv.innerHTML = \'<pre>\' + result + \'</pre>\';\n    await fetch(API + \'/vlambda/\' + data.slug, { method: \'DELETE\', headers: { \'Authorization\': \'Bearer \' + token } });\n  } catch (e) {\n    resultDiv.innerHTML = \'<pre style="color:#f85149">Error: \' + e.message + \'</pre>\';\n  }\n}\n\nasync function invokeLambda(slug, method) {\n  method = method || \'GET\';\n  try {\n    const opts = { method: method };\n    if (method === \'POST\' || method === \'PUT\' || method === \'PATCH\') {\n      opts.headers = { \'Content-Type\': \'application/json\' };\n      opts.body = \'{}\';\n    }\n    const resp = await fetch(API + \'/f/\' + slug, opts);\n    const text = await resp.text();\n    alert(slug + \' [\' + method + \']:\\n\' + text);\n  } catch (e) {\n    alert(\'Error: \' + e.message);\n  }\n}\n\nfunction openDelete(slug) {\n  deleteTarget = slug;\n  document.getElementById(\'delete-modal\').classList.remove(\'hidden\');\n}\n\nfunction closeModal() {\n  deleteTarget = null;\n  document.getElementById(\'delete-modal\').classList.add(\'hidden\');\n}\n\nasync function confirmDelete() {\n  if (!deleteTarget) return;\n  try {\n    const resp = await fetch(API + \'/vlambda/\' + deleteTarget, {\n      method: \'DELETE\',\n      headers: { \'Authorization\': \'Bearer \' + token }\n    });\n    if (resp.ok) {\n      showAlert(\'dashboard-alert\', \'Deleted\', \'success\');\n      loadLambdas();\n    } else {\n      const data = await resp.json();\n      showAlert(\'dashboard-alert\', data.error || \'Delete failed\', \'error\');\n    }\n  } catch (e) {\n    showAlert(\'dashboard-alert\', \'Network error\', \'error\');\n  }\n  closeModal();\n}\n\nlet chartInv = null;\nlet chartLat = null;\n\nasync function loadMetrics() {\n  try {\n    const resp = await fetch(API + \'/metrics/json\');\n    const data = await resp.json();\n    document.getElementById(\'m-reqs\').textContent = data.requests_total;\n    document.getElementById(\'m-errs\').textContent = data.errors_total;\n    document.getElementById(\'m-lambdas\').textContent = data.lambdas_created;\n    document.getElementById(\'m-lat\').textContent = data.latency_avg_ms.toFixed(2);\n\n    const labels = data.per_lambda.map(l => l.slug);\n    const invocations = data.per_lambda.map(l => l.invocations);\n    const latencies = data.per_lambda.map(l => l.latency_avg_ms);\n\n    if (chartInv) chartInv.destroy();\n    if (chartLat) chartLat.destroy();\n\n    chartInv = new Chart(document.getElementById(\'chart-invocations\'), {\n      type: \'bar\',\n      data: { labels: labels, datasets: [{ label: \'Invocations\', data: invocations, backgroundColor: \'#1f6feb\' }] },\n      options: { responsive: true, plugins: { legend: { display: false } }, scales: { y: { beginAtZero: true } } }\n    });\n\n    chartLat = new Chart(document.getElementById(\'chart-latency\'), {\n      type: \'bar\',\n      data: { labels: labels, datasets: [{ label: \'Avg Latency (ms)\', data: latencies, backgroundColor: \'#238636\' }] },\n      options: { responsive: true, plugins: { legend: { display: false } }, scales: { y: { beginAtZero: true } } }\n    });\n  } catch (e) {\n    console.error(\'metrics error:\', e);\n  }\n}\n\ncheckAuth();\n</script>\n</body>\n</html>\n'

